import{_ as c,o as a,c as o,a3 as l}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"命令解析","description":"语言服务器从编译数据库获知如何编译每个文件，编译数据库通常是由构建系统生成的 compile_commands.json…","frontmatter":{"head":[["meta",{"property":"og:title","content":"命令解析 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/design/command-resolve"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/design/command-resolve"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/command-resolve"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/command-resolve"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/command-resolve"}],["meta",{"property":"og:description","content":"语言服务器从编译数据库获知如何编译每个文件，编译数据库通常是由构建系统生成的 compile_commands.json…"}]]},"headers":[],"relativePath":"zh/clice/design/command-resolve.md","filePath":"zh/clice/design/command-resolve.md","lastUpdated":1794738697000}'),n={name:"zh/clice/design/command-resolve.md"};function i(s,e,t,d,r,g){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="command-resolution" tabindex="-1"><span id="命令解析" class="heading-alias"></span>命令解析 <a class="header-anchor" href="#command-resolution" aria-label="Permalink to &quot;命令解析&quot;">​</a></h1><h2 id="background" tabindex="-1"><span id="背景" class="heading-alias"></span>背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>语言服务器从编译数据库获知如何编译每个文件，编译数据库通常是由构建系统生成的 <code>compile_commands.json</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I../include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNDEBUG</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/foo.cpp</span></span></code></pre></div><p>语言服务器无法直接按原样运行这条命令：</p><ul><li><strong>这是一条驱动程序命令。</strong> <code>g++</code> 会自行选择前端、标准库和系统头文件；clice 运行的是 Clang 前端，需要将这些信息全部显式写出——目标平台、系统头文件目录、默认语言标准。这些内容都不在编译数据库中，而是由编译器提供。</li><li><strong>命令带有不影响语言服务器语义分析的选项</strong>：<code>-g</code>、<code>-c</code>、<code>-o</code>、依赖文件等。</li><li><strong>命令存在大量重复。</strong> 同一个构建目标下的一万个翻译单元共用同一个编译器及其基础选项，只在包含路径和宏定义上有所不同。</li></ul><p>其中影响最大的是缺失的隐式信息：找不到系统头文件时，<code>#include &lt;vector&gt;</code> 会报错 &quot;file not found&quot;——这一直是 clangd 收到反馈最多的问题之一（<a href="https://github.com/clangd/clangd/issues/1262" target="_blank" rel="noreferrer">clangd#1262</a>、<a href="https://github.com/clangd/clangd/issues/1691" target="_blank" rel="noreferrer">clangd#1691</a>）。clangd 只有在 <code>--query-driver</code> 点名该编译器时才会向它查询，这需要用户自行排查并手动配置（<a href="https://github.com/clangd/clangd/issues/1219" target="_blank" rel="noreferrer">clangd#1219</a>）。clice 会主动查询每条命令所用的编译器，识别其编译器家族，并将查询次数控制在很小的规模。</p><h2 id="classifying-options" tabindex="-1"><span id="选项分类" class="heading-alias"></span>选项分类 <a class="header-anchor" href="#classifying-options" aria-label="Permalink to &quot;选项分类&quot;">​</a></h2><p>每条命令使用 Clang 自身的选项表按选项 ID 解析一次：同一选项的各种写法——连写、拆写、cl 的 <code>/</code> 语法——都会归入同一类别。每个选项要么排除，要么保留在以下某一类别中：</p><ul><li><strong>排除项</strong>：仅构建流程读取的选项——输出路径、编译模式、依赖文件、耗时统计、汇编器选项、GCC 的模块映射器、cl 的模块接口输出——以及仅影响目标代码生成的选项（<code>-g</code>、<code>-ffunction-sections</code>）。看似属于代码生成但会改变预处理器的选项则保留：<code>-O</code> 会定义 <code>__OPTIMIZE__</code>，<code>-fPIC</code> 会定义 <code>__PIC__</code>，<code>-fsanitize=address</code> 会改变 <code>__has_feature</code> 的返回值。</li><li><strong>诊断</strong>：警告选项。它们只改变显示哪些诊断，不影响其他任何结果。</li><li><strong>用户内容</strong>：单个文件所需的配置——包含路径、宏定义、强制包含。它们不会改变编译器关于自身的查询结果。</li><li><strong>语义</strong>：其余选项——<code>-std</code>、<code>--target</code>、<code>-march</code>——编译器的查询结果取决于它们。</li><li><strong>预编译</strong>：命令读取或写出的 PCH，以及命令是否写出模块——这两者都由 clice 自行构建。</li><li><strong>输入</strong>，即源文件本身，占据独立槽位；以及<strong>未知</strong>选项，计入命令标识。</li></ul><p>解析后的命令集中保存在一张表中，每条命令只存一份。下游所有环节——工具链查询、规则应用、命令行渲染——均直接读取这一结构化形式；命令的标识是它的<strong>命令哈希</strong>：由保留的全部参数、输入文件的位置以及工作目录共同计算得出。索引会记录每个翻译单元的命令哈希，用户切换编译条目时也是通过它来指明目标。</p><p>这一分类也确保了编译器查询次数很少：编译器的回答不取决于用户内容，因此仅在用户内容上有差异的文件可共享同一份查询结果。数万个文件最终只会归并为几十次查询。</p><h2 id="rules-members-and-hosts" tabindex="-1"><span id="规则、成员与宿主" class="heading-alias"></span>规则、成员与宿主 <a class="header-anchor" href="#rules-members-and-hosts" aria-label="Permalink to &quot;规则、成员与宿主&quot;">​</a></h2><p><code>clice.toml</code> 中的规则在当前生效的构建配置下决定编译数据库条目的最终形态；所有使用方——编辑器、依赖扫描、后台索引、命令行工具——都向项目查询，从不直接读取编译数据库。</p><ul><li><strong>条目。</strong> 文件的编译条目按构建顺序排列：先是匹配该文件的规则所指定的编译数据库，其次是其他规则指定的数据库，最后是自动发现的数据库。第一条为默认条目，用户可手动切换为其他条目。规则只决定优先级，任何条目都不会因为文件未命中某个匹配模式而消失。</li><li><strong>编辑。</strong> 按声明顺序应用每条匹配规则的 <code>remove</code> 和 <code>append</code>。一个文件从另一个文件取得的命令（如头文件取自宿主的命令）会同时应用两个文件的规则编辑，使头文件看到的宏与宿主编译时一致。</li><li><strong>成员。</strong> 构建中的翻译单元：拥有数据库条目的文件、被某条规则的 <code>default_command</code> 覆盖的源文件，以及临时成员（见下文）。编译数据库中列出的头文件同样属于成员，会作为独立的翻译单元建立索引。</li><li><strong>宿主。</strong> 没有独立编译命令的头文件会在某个包含它的翻译单元中参与编译，且该单元的语言必须与头文件兼容（<code>.hpp</code> 绝不会按 C 编译）。候选单元依次按头文件自身规则指定的数据库、同名文件主干、同目录以及路径距离排序；其中第一个在编译时实际进入该头文件的单元即成为其宿主。参见<a href="./compilation-context">编译上下文</a>。</li><li><strong>借用的命令。</strong> 既无条目、无宿主，也无 <code>default_command</code> 的文件会向附近同语言的翻译单元借用命令：优先取同目录下的单元（其中共享文件主干的排最前），否则对头文件而言取包含目录涵盖它的单元，最后取路径最近的单元。借用的命令会标明来源，缺失文件的诊断也会说明该命令是借来的。</li><li><strong>临时成员。</strong> 用户打开或保存的项目源文件若既未列在任何编译数据库中，也未被任何翻译单元包含——例如生成编译数据库之后新建的文件，或无编译数据库项目中的源文件——就会以借用的命令（无可借用时则用 clice 内置命令）加入构建：它会建立索引、向外提供自身声明的模块，并充当所包含头文件的宿主。被其他翻译单元包含的源文件（如 合并构建（unity build）的组成部分）则改为在包含它的单元上下文中编译。临时成员记录在重启后依然保留；一旦有编译数据库列出了该文件，即由数据库接管。</li></ul><h3 id="discovery" tabindex="-1"><span id="发现" class="heading-alias"></span>发现 <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;发现&quot;">​</a></h3><p>未声明任何编译数据库也未声明 <code>default_command</code> 的配置会自动发现数据库：查找项目根目录及其直接子目录中的 <code>compile_commands.json</code>，并在打开文件时查找从该文件所在目录到根目录之间各级目录中的数据库。自身含有 <code>clice.toml</code> 或 <code>.clice/config.toml</code> 的目录视为另一个独立项目。指向已发现数据库的符号链接视为同一份数据库。服务器会在轮询时持续查找，因此稍后生成的数据库一旦出现就会加载。只要有任何规则显式声明了命令来源，自动发现就会关闭：显式声明即代表完整意图。</p><h2 id="asking-the-compiler" tabindex="-1"><span id="查询编译器" class="heading-alias"></span>查询编译器 <a class="header-anchor" href="#asking-the-compiler" aria-label="Permalink to &quot;查询编译器&quot;">​</a></h2><p>每个编译器家族都按各自的方式查询，每个不同的查询键只问一次，并将结果缓存起来：</p><ul><li><strong>GCC 风格驱动程序</strong>（GCC、clang、Apple clang、emcc、zig、交叉编译与裸机 GCC）使用命令自身的标志，以详细输出并打印宏定义的方式（<code>-E -dM -v</code>）预处理一个对应语言的空文件。一次运行即可获知全部信息：clang 驱动程序会打印 clice 所需运行的前端任务；GCC 会打印目标平台、头文件搜索列表以及 specs 注入的选项，再由 clang 驱动程序锁定该目标平台并结合 GCC 的搜索列表拼出前端命令。输出的宏会给出默认语言标准。驱动程序底层是 clang 还是 GCC 由其输出内容判定，从不看文件名：macOS 上的 <code>/usr/bin/c++</code> 实际上是 clang。</li><li><strong>cl 与 clang-cl</strong> 预处理一个写有 <code>_MSVC_LANG</code> 和 <code>_MSC_FULL_VER</code> 的文件，以获取语言标准以及 cl 的编译器版本，再由处于 cl 模式的 clang 驱动程序构建前端命令。</li><li><strong>nvcc</strong> 通过试运行给出 CUDA 根目录、宿主编译器、nvcc 宏定义及其头文件目录；GCC 或 clang 宿主编译器按上述方式继续查询，最后由 clang 驱动程序构建 CUDA 编译命令。</li><li><strong>clice 不主动运行的编译器</strong>——规则设置了 <code>query_toolchain = false</code>，或查询失败的编译器——会将命令直接交给 clang 自身的驱动程序，按以该名称安装的 clang 来解析；查询失败时会在受影响文件的顶部显示错误信息。</li></ul><p>无法直接沿用的查询结果会针对 clang 做适配。GCC 的私有头文件目录中既混有 clang 无法解析的 GCC 版内置头文件，也有仅 GCC 提供的头文件（如 <code>omp.h</code>）：clice 会保留该目录，并隐藏其中可由 clang 自带头文件替代的文件；丢弃 clang 不认识的 CPU 与 ABI 名称；把 GCC、cl 和 nvcc 升级为错误的警告降回普通警告，因为 clang 会报告那些编译器从不报告的警告；将 GCC 的 <code>-fmodules</code> 解释为 C++20 模块，而非 clang 的头文件模块。编译器前面的启动器（ccache、sccache、distcc、icecc）会先剥离。</p><p>启动时，构建涉及的所有不同工具链查询会在依赖扫描阶段并行发起，使首批编译直接命中缓存。</p><h2 id="search-paths" tabindex="-1"><span id="搜索路径" class="heading-alias"></span>搜索路径 <a class="header-anchor" href="#search-paths" aria-label="Permalink to &quot;搜索路径&quot;">​</a></h2><p>前端命令的包含目录按 Clang 的顺序归入四层——双引号目录（<code>-iquote</code>）、尖括号目录（<code>-I</code>）、系统目录与后置目录（<code>-idirafter</code>）——并按 Clang 的规则去重：同时出现在尖括号组和系统组中的目录，会在系统组所在的位置参与搜索。clice 自身的头文件查找、依赖扫描与 <code>#include</code> 代码补全都沿用这一顺序，确保 <code>#include_next</code> 与同名头文件解析到的文件与编译器完全一致。</p><h2 id="faq" tabindex="-1"><span id="常见问题" class="heading-alias"></span>常见问题 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>为什么 GCC 命令会按 clang 解析？</strong> clice 的前端是 clang。标识编译器的宏保留为 clang 的定义——即定义了 <code>__clang__</code>——因为若改用 GCC 的标识宏，会让代码走入专为 GCC 编写的分支，其中充斥着 clang 无法解析的内置函数。其余描述构建环境的信息则全部跟随真实编译器：目标平台、头文件搜索列表、语言标准以及编译器配置注入的宏。</li><li><strong>为什么按命令中写出的名称查询，而不先解析真实路径？</strong> 驱动程序的行为取决于被调用的名称：<code>clang++</code> 是指向 <code>clang</code> 的链接，靠名称开启 C++ 模式；<code>arm-none-eabi-g++</code> 则在名称中编码了目标平台。提前解析链接会同时丢失这两项信息。</li><li><strong>为什么搜索顺序必须与 Clang 完全一致？</strong> 两个同名头文件中究竟包含哪一个，以及 <code>#include_next</code> 从何处继续向后查找，都由搜索顺序决定。任何偏差都会让用户看到与实际编译不一致的代码。</li></ul><h2 id="known-limitations" tabindex="-1"><span id="已知限制" class="heading-alias"></span>已知限制 <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><ul><li><strong>自动发现不会递归扫描整个目录树。</strong> 嵌套子项目的编译数据库会在打开其中某个文件时加载；在规则中显式指定该数据库即可从一开始就覆盖它。</li><li><strong>只有编辑器会将未列出的文件加入构建。</strong> 通过其他方式出现在磁盘上、既未列在任何编译数据库中也未被规则的 <code>default_command</code> 覆盖的源文件，在被打开或保存之前（或重新生成的数据库列出它之前）一直处于构建之外。</li><li><strong>GCC 专属代码按 clang 的视角解析</strong>：仅 GCC 支持的内置函数、clang 不支持平台上的 <code>__float128</code> 以及嵌套函数，都会显示 clang 的报错。</li><li><strong>CUDA 按 clang 的 CUDA 模式解析</strong>：仅 nvcc 接受的语法会显示 clang 的报错。</li><li><strong>既不按 clang 也不按 GCC 格式输出的驱动程序</strong>——例如 Intel 传统编译器 <code>icc</code> 或其他厂商的专有编译器——会回退为 clang 针对本机的默认配置，并在诊断错误中说明这一点。</li><li><strong>仅识别常见的编译器启动器。</strong> 其他启动器会被误认为编译器本身，请先将其从编译数据库中剥离。</li><li><strong>clice 自身的头文件查找不读取 Header Map</strong>（影响依赖扫描、补全和文档链接），但实际编译仍会正常应用它们。</li><li><strong>不跟随头文件中的 Cygwin 符号链接</strong>：clice 内置的 clang 会把链接文件本身当作普通文件读取。</li><li><strong>导出给外部工具的命令会省去含被隐藏文件的目录。</strong> <code>clice command convert</code> 输出的命令不含 GCC 私有头文件目录及其他版本 clang 的内置头文件目录；<code>clice command &lt;file&gt; --json</code> 会列出各目录中被隐藏的文件。</li></ul>',28)])])}const m=c(n,[["render",i]]);export{p as __pageData,m as default};
